import {rainfall,waterCases,endStorage} from './drought-data.js?v=20261023-ecosystems01';
export const weatherViews4={
 'weather-drought-causes':[['aridity','Aridity vs drought'],['lag','Rain to stored water'],['agriculture','Soil & crop demand'],['human','Dams & abstraction'],['forest','Vegetation pathways']],
 'weather-drought-patterns':[['descent','Subtropical descent'],['season','Moving rain belts'],['variability','Changing risk'],['rain','1990–2015 graph'],['table','Estimated annual values']],
 'weather-australia-drought':[['stores','Melbourne storage'],['people','People & supply'],['wetlands','Wetland connections'],['allocation','Dry-period budget'],['saving','Lower-use budget']],
 'weather-somalia-drought':[['cascade','Food-access cascade'],['grazing','Water & pasture'],['mortality','Dated study estimates'],['access','Access & uncertainty']],
 'weather-drought-response':[['australia','Australia responses'],['somalia','Somalia responses'],['coverage','Dated aid snapshot'],['compare','Compare outcomes']]
};
export const weatherRequirements4=Object.fromEntries(Object.entries(weatherViews4).map(([k,v])=>[k,v.map(x=>x[0])]));
export const weatherAnimated4=(k,v)=>k==='weather-drought-causes'?['lag','agriculture','human'].includes(v):k==='weather-drought-patterns'?['descent','season'].includes(v):k==='weather-australia-drought'?v!=='stores':k==='weather-somalia-drought'?['cascade','grazing'].includes(v):k==='weather-drought-response'?['australia','somalia'].includes(v):false;
const tx=(x,y,s,z=13)=>`<text x="${x}" y="${y}" font-size="${z}">${s}</text>`;
const path=(d,c='#b6d5de',w=3,extra='')=>`<path d="${d}" fill="none" stroke="${c}" stroke-width="${w}" ${extra}/>`;
const ar=(x,y,a,b)=>path(`M${x} ${y}L${a} ${b}`,'#efb49f',3,'marker-end="url(#w4Arrow)"');
const dot=(x,y,r=6,c='#efb49f')=>`<circle cx="${x}" cy="${y}" r="${r}" fill="${c}"/>`;
const box=(x,y,w,h,s)=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="10" fill="#38576c" stroke="#a4bfc8"/>`+tx(x+10,y+26,s,12);
const svg=(b,c)=>`<svg class="geo-scene" viewBox="0 0 440 350" role="img" aria-label="${c.replaceAll('&','&amp;').replaceAll('"','&quot;')}"><defs><marker id="w4Arrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="5" markerHeight="5" orient="auto"><path d="M0 0L10 5 0 10Z" fill="#efb49f"/></marker></defs><g fill="#eef2f2" font-family="sans-serif">${b}</g></svg>`;
const wrap=(b,c)=>svg(b,c)+`<p class="geo-caption">${c}</p>`;
const link=(url,s)=>`<a href="${url}" target="_blank" rel="noopener">${s}</a>`;
const table=(cap,heads,rows)=>`<table class="geo-data"><caption>${cap}</caption><thead><tr>${heads.map(s=>`<th scope="col">${s}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr><th scope="row">${r[0]}</th>${r.slice(1).map(s=>`<td>${s}</td>`).join('')}</tr>`).join('')}</tbody></table>`;
const rainSource=`NASA POWER ${rainfall.apiVersion} · MERRA-2 gridded precipitation estimates · requested point37.81°S144.96°E near Melbourne ·1990–2015 · annual mm from monthly mean mm/day × days/month,rounded to nearest mm. Not a rain-gauge record or regional average. Retrieved23October2026. ${link('https://power.larc.nasa.gov/docs/methodology/meteorology/precipitation/','NASA method')} · ${link('./geography/data/power-melbourne-1990-2015.json','Archived source values')}.`;
export function droughtRain(view='rain'){
 const rows=view==='rain-pair'?rainfall.annual.filter(([y])=>[2006,2010].includes(y)):rainfall.annual;
 if(view==='table')return table('NASA POWER estimated annual precipitation · near Melbourne · mm',['Year','Estimated mm'],rows)+`<p class="geo-caption">${rainSource}</p>`;
 let b=tx(20,27,'NEAR MELBOURNE · GRIDDED ESTIMATES',14)+tx(20,51,'Annual precipitation (mm) · MERRA-2 / NASA POWER',11),label='';
 const Y=v=>280-v/1000*205;
 for(let v=0;v<=1000;v+=250)b+=path(`M55 ${Y(v)}H415`,'#7d99aa',1)+tx(10,Y(v)+4,''+v,11);
 if(view==='rain-pair'){rows.forEach(([y,v],i)=>{const x=105+i*180;b+=`<rect x="${x}" y="${Y(v)}" width="75" height="${280-Y(v)}" rx="5" fill="${i?'#eeb39e':'#b3d5dd'}"/>`+tx(x+22,Y(v)-10,v+'',14)+tx(x+18,305,''+y,12);});label='Selected estimated annual precipitation at the requested Melbourne-area coordinate:2006,487mm;2010,935mm. Vertical axis starts0mm; these are gridded estimates,not station observations.';}
 else{const X=y=>55+(y-1990)/25*350;b+=`<rect x="${X(1997)}" y="75" width="${X(2009)-X(1997)}" height="205" fill="#dcb492" opacity=".12"/>`+path(rows.map(([y,v],i)=>(i?'L':'M')+X(y).toFixed(2)+' '+Y(v).toFixed(2)).join(' '),'#f2b59f',2);for(const[y,v]of rows)b+=dot(X(y),Y(v),2,'#eec4b2');for(const y of[1990,1995,2000,2005,2010,2015])b+=tx(X(y)-14,305,''+y,11);label='NASA POWER gridded estimates of annual precipitation1990–2015 near Melbourne in millimetres. Vertical axis0–1000mm. Shading marks the often-studied1997–2009southeastern drought period,not a claim that every annual value or location had the same conditions.';}
 b+=tx(190,335,'Year',12);
 return svg(b,label)+`<p class="geo-caption">${rainSource}${view==='rain-pair'?'':' Shading:1997–2009,southeastern core drought period;not every year or place was equally dry.'}</p><details class="geo-chart-values"><summary>Read chart values</summary>${table('Same plotted annual estimates · mm',['Year','Estimated mm'],rows)}</details>`;
}
export function droughtEvidence(v){
 if(['rain','rain-pair'].includes(v))return droughtRain(v);
 if(v==='storage')return table('Melbourne water storages · dated snapshots · percent of capacity',['Date','Storage %'],[['October1996','97.5'],['June2010','33.0']])+`<p class="geo-caption">${link('https://www.bom.gov.au/climate/updates/articles/a010-southern-rainfall-decline.shtml','Bureau of Meteorology,2015 article')}. Different months/years;storage percentages,not river flow or a direct rainfall measurement.</p>`;
 if(v==='mortality')return table('Southern and central Somalia · October2010–April2012 · estimated excess deaths',['Population','Estimate'],[['All ages','258,000'],['Of all ages:children under5','133,000']])+`<p class="geo-caption">${link('https://fsnau.org/in-focus/press-release-study-suggests-258000-somalis-died-due-severe-food-insecurity-and-famine-half','FSNAU/FEWSNET study release,2May2013')}. Modelled deaths associated with famine/severe food insecurity above an expected baseline;not an exact register or a dehydration-only count.</p>`;
 if(v==='coverage')return table('Southern Somalia · urgent food-assistance needs · UN snapshot4August2011',['Indicator','Estimate'],[['People in urgent need','2,800,000'],['Proportion being reached','20%']])+`<p class="geo-caption">${link('https://www.un.org/sg/en/content/highlight/2011-08-04.html','UN4August2011 briefing')}. Approximate dated coverage,not current conditions,a final total or proof of needs fully met.</p>`;
 return '';
}
export function weatherScene4(k,selected,t=0){if(!weatherViews4[k])return '';const v=weatherViews4[k].some(x=>x[0]===selected)?selected:weatherViews4[k][0][0];t=Math.min(1,Math.max(0,Number(t)||0));if(!weatherAnimated4(k,v))t=0;let b='',c='';
 if(k==='weather-drought-causes'){
  if(v==='aridity'){b=tx(24,30,'LONG-TERM CLIMATE ≠ UNUSUAL SHORTAGE',14)+box(25,85,390,60,'Aridity:usually low precipitation / high demand')+box(25,185,390,60,'Drought:unusual shortage for that place')+tx(25,300,'Arid vegetation can be adapted to water scarcity',12)+tx(25,330,'Drought can also occur in normally wet climates',12);c='Compare local climate and water needs over a relevant period. Aridity is persistent climatic dryness;drought is an unusual prolonged shortage. Dry environments are not necessarily hot or vegetation-free;one dry day or a normal dry season is not automatically drought.';}
  else if(v==='lag'){b=tx(24,30,'RAINFALL → SOIL → DEEPER STORES',14)+box(25,75,110,55,'Precipitation')+box(165,145,110,55,'Soil moisture')+box(285,230,130,55,'Groundwater')+ar(100,138,175,172)+ar(255,210,315,235)+dot(100+75*t,138+34*t)+dot(255+60*t,210+25*t,6,'#b7dce6')+tx(25,312,'A shower may wet soil before deeper stores recover',12)+tx(25,338,'Conceptual pathways · responses occur at different speeds',11);c='Water moves into soil and can percolate into groundwater,while runoff feeds streams and reservoirs. Recovery times differ;one shower need not end hydrological drought. Dots illustrate transfer and lag,not measured travel times,exact proportions or a complete catchment model.';}
  else if(v==='agriculture'){const h=105-45*t;b=tx(24,30,'SOIL WATER SUPPLY AND CROP DEMAND',14)+'<rect x="25" y="220" width="390" height="100" rx="8" fill="#a39681"/>'+`<rect x="45" y="${320-h}" width="100" height="${h}" fill="#759eaa"/>`+path('M260 235V105m0 28l-25-18m25 45l30-19','#c5d4ad',7)+ar(125,270,235,245)+ar(275,105,275,55)+dot(125+110*t,270-25*t)+tx(25,340,'Inadequate soil moisture → crop stress',12);c='Crop water use and evaporation can exceed replenishment during a dry period,reducing soil moisture. Agricultural drought concerns water available to plants,not just farming as a cause. This conceptual store declines in invented proportions;it is not a farm forecast or measured water volume.';}
  else if(v==='human'){b=tx(24,30,'UPSTREAM STORAGE / USE ↔ DOWNSTREAM WATER',13)+'<path d="M25 220H415V290H25Z" fill="#6798ad"/><path d="M190 180V295H210V180Z" fill="#b8c5c5"/>'+ar(60,240,155,240)+ar(260,255,390,255)+ar(130,215,130,125)+dot(60+95*t,240)+dot(130,215-90*t)+tx(35,100,'Abstraction',13)+tx(260,190,'Reduced / managed release',11)+tx(25,330,'Dams can buffer supply but also alter downstream flow',11);c='Dams can store water and regulate releases,while abstraction removes water for uses such as irrigation. Retention or diversion can reduce downstream availability during shortage. Arrows are schematic,not a measurement of a particular dam;storage and allocation can also reduce some drought impacts.';}
  else{b=tx(24,30,'VEGETATION CHANGES SEVERAL WATER PATHWAYS',13)+box(25,75,390,48,'Canopy / soil cover → interception and runoff')+box(25,150,390,48,'Roots / soil condition → infiltration')+box(25,225,390,48,'Evapotranspiration → moisture recycling')+tx(25,330,'Outcomes depend on soils,climate,land use and scale',11);c='Removing vegetation can alter infiltration,erosion,runoff and evapotranspiration. It need not always reduce river flow;local and regional effects differ. The diagram is a causal framework,not a universal deforestation-to-drought rule or a measured budget.';}
 }
 if(k==='weather-drought-patterns'){
  if(v==='rain'||v==='table')return droughtRain(v);
  if(v==='descent'){b=tx(24,30,'HADLEY DESCENT · BROAD SUBTROPICAL DRY BELT',13)+path('M25 280H415','#a7bab8',9)+ar(100,225,100,90)+ar(110,85,325,85)+ar(335,100,335,245)+dot(335,100+145*t,7)+tx(40,55,'Equator',14)+tx(280,55,'Subtropics',14)+tx(24,315,'Descending air warms and often suppresses cloud',12)+tx(24,340,'Approximate belts,not fixed local weather forecasts',11);c='Air rises in the tropics and descends in the subtropics within the broad Hadley circulation. Descent tends to inhibit clouds and rain,helping explain many dry regions. Belts migrate and local conditions differ;this is not a diagnosis of drought from latitude alone.';}
  else if(v==='season'){const y=150+45*Math.cos(t*2*Math.PI);b=tx(24,30,'SEASONAL RAIN-BELT MIGRATION',14)+'<rect x="25" y="70" width="390" height="230" rx="12" fill="#547887"/>'+path('M25 185H415','#e2d5b6',1,'stroke-dasharray="5 4"')+`<rect x="25" y="${y}" width="390" height="35" rx="10" fill="#b8d6db" opacity=".7"/>`+tx(28,96,'North',12)+tx(28,280,'South',12)+tx(290,180,'Equator',12)+tx(25,330,'Weak,delayed or displaced wet seasons can raise risk',11);c='A conceptual tropical rain belt shifts with seasons,changing which places receive rain. Its real position,width and strength vary by region and circulation. The motion is not a global uniform calendar,measured rainfall map or prediction that every dry season is drought.';}
  else{b=tx(24,30,'RISK CHANGES ACROSS TIMESCALES',14)+box(25,75,390,48,'Seasonal rain-belt / front migration')+box(25,150,390,48,'Ocean–atmosphere variability and persistent highs')+box(25,225,390,48,'Long-term warming + changing demand / exposure')+tx(25,330,'El Niño changes probabilities,not every local outcome',11);c='Drought risk reflects circulation,seasonal rain,climate variability,longer-term warming and water demand. Southern Australian ridge position/strength affects rain-bearing fronts. Do not infer one event’s cause from an annual line alone. Sources:Bureau of Meteorology subtropical-ridge and rainfall analyses;NOAA drought explanations.';}
 }
 if(k==='weather-australia-drought'){
  if(v==='stores')return droughtEvidence('storage');
  if(v==='people'){b=tx(24,30,'SUPPLY SHORTFALL → PEOPLE AND LIVELIHOODS',13)+box(25,75,390,48,'Low inflows / stores')+box(25,155,180,55,'Household restrictions')+box(235,155,180,55,'Irrigation allocations')+ar(130,130,130,150)+ar(320,130,320,150)+dot(130,130+20*t)+dot(320,130+20*t)+tx(25,280,'Farm output / income and public supplies affected',12)+tx(25,330,'Exposure and access differ between communities',12);c='During the Millennium Drought,water restrictions and reduced irrigation allocations affected households,farmers and regional communities. Dots show a causal explanation,not exact supply transfers or a measure of every household’s experience. Sources:BOM,Melbourne Water and SouthAustralia government.';}
  else if(v==='wetlands'){const width=16*(1-t);b=tx(24,30,'REDUCED FLOWS AND WETLAND CONNECTIONS',13)+'<ellipse cx="110" cy="210" rx="75" ry="55" fill="#78a4b4"/><ellipse cx="335" cy="210" rx="75" ry="55" fill="#78a4b4"/>'+path('M180 210H260','#9ecbd7',Math.max(.5,width))+path('M220 175V245','#e8b59f',3)+tx(55,125,'River / lake',13)+tx(300,125,'Wetland',13)+tx(25,310,'Disconnecting habitats can alter plants and ecology',12)+tx(25,335,'Schematic connectivity,not Lower Lakes bathymetry',11);c='SouthAustralia records33wetlands temporarily disconnected to save water during drought,with ecological risks and colonisation by introduced terrestrial plants. Low flows also disrupted Lower Lakes connections. The narrowing link is schematic,not a measured closure sequence or a claim that every wetland responded identically.';}
  else{const example=v==='saving'?waterCases.saving:waterCases.dry,end=endStorage(example),stored=example.start+(end-example.start)*t;b=tx(24,30,'INVENTED ONE-PERIOD WATER BUDGET',14)+`<rect x="45" y="85" width="135" height="190" rx="12" fill="none" stroke="#d2e2e7" stroke-width="3"/><rect x="48" y="${272-stored*1.6}" width="129" height="${stored*1.6}" fill="#7eacbd"/>`+tx(215,110,'Start:100units',13)+tx(215,145,'Inflow:10units',13)+tx(215,180,'Use:'+example.use+'units',13)+tx(215,215,'Other loss:10units',13)+tx(215,250,'End:'+end+'units',15)+tx(25,315,'End = start + inflow − use − other loss',12)+tx(25,340,'Same inflow;lower use leaves more in storage',11);c=`Invented teaching budget,not Murray or Melbourne observations. Start${example.start}+inflow${example.inflow}−use${example.use}−other loss${example.loss}=end${end}units. Fill interpolates the net storage change,not independently measured flows;loop resets the same scenario. Otherloss represents evaporation or other specified losses,not all river releases.`;}
 }
 if(k==='weather-somalia-drought'){
  if(v==='mortality')return droughtEvidence('mortality');
  if(v==='cascade'){const stage=Math.min(2,Math.floor(t*3));b=tx(24,30,'SOMALIA2010–12 · INTERACTING SHOCKS',14)+box(25,70,390,48,'Poor rains → crop / livestock / income losses')+box(25,150,390,48,'Food prices + poverty + conflict / access barriers')+box(25,230,390,48,'Food insecurity / malnutrition / displacement')+dot(15,94+stage*80,5)+ar(220,125,220,145)+ar(220,205,220,225)+tx(25,330,'A drought is not an automatic famine',12);c='Poor Deyr2010andGu2011rains interacted with livelihood losses,food prices,conflict and access constraints. The highlighted steps show a causal account,not a complete causal model,measured progression or rule that all droughts produce famine. Source:FAO/FSNAU/FEWSNET historical assessments.';}
  else if(v==='grazing'){const extent=210-100*t;b=tx(24,30,'PASTURE AND WATER SUPPORT LIVELIHOODS',13)+'<rect x="25" y="225" width="390" height="100" fill="#9caa91"/>'+`<ellipse cx="110" cy="265" rx="${50-25*t}" ry="20" fill="#739eb1"/>`;for(let i=0;i<7;i++)b+=path(`M${210+i*25} 285v-${30-15*t}m0 8l-6-6`,'#cfdbad',3);b+=tx(25,80,'Less water / pasture → poorer animal condition',12)+tx(25,120,'Herd losses → food / income and asset losses',12)+tx(25,170,'Remaining grazing can face extra local pressure',12)+tx(25,340,'Conceptual illustration,not a measured site time series',11);c='Pastoral livelihoods depend on water,pasture and livestock condition. Shortages can reduce herds and concentrate pressure around remaining resources. Actual ecosystem effects depend on location,management and movement. The shrinking water/grass illustration is not a satellite record or a quantified national vegetation loss.';}
  else{b=tx(24,30,'WHAT DOES EACH SOURCE SUPPORT?',14)+box(25,75,390,48,'Rainfall evidence:weather / climate conditions')+box(25,150,390,48,'Food / price / livelihood records:access pressures')+box(25,225,390,48,'Mortality model:estimated excess deaths')+tx(25,330,'Keep geography,period,definition and uncertainty',12);c='The2013study estimates excess mortality above a baseline for southern/central Somalia duringOctober2010–April2012. It is not a precise register or a dehydration-only count. Different sources measure different variables;they cannot be merged into one weather-only causal claim.';}
 }
 if(k==='weather-drought-response'){
  if(v==='coverage')return droughtEvidence('coverage');
  if(v==='compare'){b=tx(24,30,'COMPARE ACTIONS,ACCESS AND TRADE-OFFS',14)+box(25,75,390,48,'Immediate:water / food / nutrition / access')+box(25,150,390,48,'Recovery:assets / water systems / livelihoods')+box(25,225,390,48,'Future risk:allocation / preparedness / institutions')+tx(25,330,'Capacity and inequality differ within countries too',12);c='Both cases involved communities,organisations and authorities. Australia’s infrastructure/resources did not remove ecological or livelihood costs;Somalia’s insecurity and access barriers limited assistance. Cash is not sufficient without safe markets or where people cannot work. Compare evidence and outcomes rather than treating national development labels as complete explanations.';}
  else{const au=v==='australia';b=tx(24,30,au?'AUSTRALIA · DEMAND AND SUPPLY':'SOMALIA · RELIEF AND RECOVERY',14)+box(25,75,180,60,au?'Households / utilities':'Local / diaspora networks')+box(235,75,180,60,au?'State / water authorities':'Agencies / authorities')+box(90,235,260,50,au?'Water access / future resilience':'Food,water and productive assets')+ar(110,150,175,220)+ar(325,150,275,220)+dot(110+65*t,150+70*t)+dot(325-50*t,150+70*t)+tx(25,190,au?'Target155 / restrictions / later diversification':'Water,nutrition,seeds,livestock and cash support',11)+tx(25,330,'Roles and causal links,not measured delivery routes or speed',11);c=au?'Melbourne households conserved water;utilities promoted Target155from2008 and authorities restricted use and invested in supply. Victoria’s desalination plant completed2012,after the core drought period,with first ordered water2017. Diagram routes/timing are symbolic. Sources:Melbourne Water and Victorian government.':'Local people,businesses and diaspora contributed funds/assistance;agencies supplied relief and supported livelihoods. UN2011records government/municipal coordination;FAO cash-for-work repaired productive assets. Resources,access and insecurity constrained action. These lines show roles,not actual routes,speed or equal coverage. Sources:UN,UNICEF evaluation andFAO2011.';}
 }
 return wrap(b,c);
}
